CREATE TABLE IF NOT EXISTS community_shared_value_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, plan_version integer NOT NULL DEFAULT 1, plan_status text NOT NULL DEFAULT 'Draft', community_readiness text NOT NULL DEFAULT 'Not Ready', economic_participation text NOT NULL DEFAULT 'Not Assessed', benefit_commitment_status text NOT NULL DEFAULT 'Not Assessed', monitoring_status text NOT NULL DEFAULT 'Not Assessed', audit_status text NOT NULL DEFAULT 'Not Assessed', investment_gate text NOT NULL DEFAULT 'Blocked', rationale text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,plan_version));
CREATE TABLE IF NOT EXISTS community_value_commitments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_shared_value_plans(id) ON DELETE CASCADE, commitment_type text NOT NULL, description text NOT NULL, beneficiary_group text, delivery_mechanism text, target_value text, currency text, frequency text, start_date date, end_date date, responsible_party text, evidence_required text, status text NOT NULL DEFAULT 'Proposed', community_position text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_value_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), commitment_id uuid NOT NULL REFERENCES community_value_commitments(id) ON DELETE CASCADE, metric_name text NOT NULL, baseline text, target text, unit text, measurement_method text, reporting_frequency text, current_value text, verification_status text NOT NULL DEFAULT 'Pending', evidence_reference text, measured_at timestamptz, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS community_value_distributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), commitment_id uuid NOT NULL REFERENCES community_value_commitments(id) ON DELETE CASCADE, distribution_period text NOT NULL, beneficiary_group text, amount_or_value text, distribution_status text NOT NULL DEFAULT 'Planned', evidence_reference text, verified_by_reference text, distributed_at timestamptz, notes text, status text NOT NULL DEFAULT 'Recorded');
CREATE TABLE IF NOT EXISTS community_value_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES community_shared_value_plans(id) ON DELETE CASCADE, audit_type text NOT NULL, audit_period text, auditor_reference text, scope_summary text, findings text, exceptions text, corrective_action text, audit_status text NOT NULL DEFAULT 'Planned', evidence_reference text, audited_at timestamptz, status text NOT NULL DEFAULT 'Recorded');
CREATE TABLE IF NOT EXISTS asset_readiness_dimensions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, dimension_code text NOT NULL, dimension_name text NOT NULL, readiness_status text NOT NULL DEFAULT 'Not Assessed', blocking boolean NOT NULL DEFAULT false, confidence_score numeric(6,2), rationale text, evidence_reference text, assessed_at timestamptz NOT NULL DEFAULT now(), assessor_reference text, UNIQUE(asset_id,dimension_code));
CREATE INDEX IF NOT EXISTS idx_shared_value_asset ON community_shared_value_plans(asset_id,plan_version DESC);
CREATE INDEX IF NOT EXISTS idx_value_commitments_plan ON community_value_commitments(plan_id,status);
CREATE INDEX IF NOT EXISTS idx_value_metrics_commitment ON community_value_metrics(commitment_id,verification_status);
CREATE INDEX IF NOT EXISTS idx_value_distributions_commitment ON community_value_distributions(commitment_id,distribution_status);
CREATE INDEX IF NOT EXISTS idx_value_audits_plan ON community_value_audits(plan_id,audited_at DESC);
CREATE INDEX IF NOT EXISTS idx_readiness_asset ON asset_readiness_dimensions(asset_id,dimension_code);